package pzvrphysicality;
import java.nio.file.*;import java.util.*;import java.util.jar.*;import net.bytebuddy.dynamic.ClassFileLocator;import net.bytebuddy.pool.TypePool;import net.bytebuddy.description.type.TypeDescription;import net.bytebuddy.jar.asm.*;
public final class SurfaceReferenceContract {
 static int lastChecks;
 record Ref(String source,String owner,String name,String desc,boolean field,int opcode){}
 static TypeDescription locate(TypePool pool,String name){return pool.describe(name.replace('/','.')).resolve();}
 static Object member(TypeDescription type,Ref r,Set<String> seen){if(type==null||!seen.add(type.getName()))return null;if(r.field){for(var f:type.getDeclaredFields())if(f.getName().equals(r.name)&&f.getDescriptor().equals(r.desc))return f;}else{for(var m:type.getDeclaredMethods())if(m.getInternalName().equals(r.name)&&m.getDescriptor().equals(r.desc))return m;if(r.name.equals("<init>"))return null;}if(type.getSuperClass()!=null){Object found=member(type.getSuperClass().asErasure(),r,seen);if(found!=null)return found;}for(var i:type.getInterfaces()){Object found=member(i.asErasure(),r,seen);if(found!=null)return found;}return null;}
 public static void main(String[] a)throws Exception{var refs=new LinkedHashSet<Ref>();try(var jar=new JarFile(a[0])){for(var entry:Collections.list(jar.entries())){if(!entry.getName().endsWith(".class"))continue;new ClassReader(jar.getInputStream(entry)).accept(new ClassVisitor(Opcodes.ASM9){public MethodVisitor visitMethod(int access,String name,String descriptor,String signature,String[] errors){return new MethodVisitor(Opcodes.ASM9){void add(String owner,String member,String desc,boolean field,int opcode){if(owner.startsWith("zombie/")||owner.startsWith("viewpoint/"))refs.add(new Ref(entry.getName()+":"+name,owner,member,desc,field,opcode));}public void visitMethodInsn(int opcode,String owner,String member,String desc,boolean itf){add(owner,member,desc,false,opcode);}public void visitFieldInsn(int opcode,String owner,String member,String desc){add(owner,member,desc,true,opcode);}};}},ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);}}
 var errors=new ArrayList<String>();int checked=0;try(var locator=new ClassFileLocator.Compound(ClassFileLocator.ForJarFile.of(Path.of(a[1]).toFile()),ClassFileLocator.ForJarFile.of(Path.of(a[2]).toFile()),ClassFileLocator.ForClassLoader.of(SurfaceReferenceContract.class.getClassLoader()))){var pool=TypePool.Default.of(locator);for(var r:refs){try{var owner=locate(pool,r.owner);var found=member(owner,r,new HashSet<>());if(found==null){errors.add("MISSING "+r);continue;}boolean pub,isStatic;if(found instanceof net.bytebuddy.description.field.FieldDescription f){pub=f.isPublic();isStatic=f.isStatic();}else{var m=(net.bytebuddy.description.method.MethodDescription)found;pub=m.isPublic();isStatic=m.isStatic();}boolean expectsStatic=r.opcode==Opcodes.INVOKESTATIC||r.opcode==Opcodes.GETSTATIC||r.opcode==Opcodes.PUTSTATIC;if(!pub)errors.add("ACCESS "+r);if(expectsStatic!=isStatic)errors.add("STATIC "+r);checked++;}catch(RuntimeException e){errors.add("UNRESOLVED "+r+" "+e);}}}
 lastChecks=checked;Files.write(Path.of(a[3]),errors);System.out.println("Surface native reference audit: "+checked+" symbolic references checked, "+errors.size()+" findings; original classes not initialized");for(String e:errors)System.out.println(e);if(!errors.isEmpty())System.exit(2);
 }
}